import { Injectable, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

/**
 * A captured payment intent. `amount` is the ceiling that all refunds
 * against this intent must never exceed in total.
 */
export interface PaymentIntent {
  id: string;
  amount: number; // captured amount, in cents
}

export type RefundStatus = 'succeeded' | 'failed';

/**
 * A single row in the refund ledger. Every refund attempt is persisted
 * here, whether the gateway completed it or declined it — the ledger
 * is the source of truth for what actually left the captured amount.
 */
export interface Refund {
  id: string;
  paymentIntentId: string;
  amount: number;
  status: RefundStatus;
}

@Injectable()
export class RefundService {
  constructor(
    @InjectRepository(PaymentIntent)
    private readonly intentRepo: Repository<PaymentIntent>,
    @InjectRepository(Refund)
    private readonly refundRepo: Repository<Refund>,
  ) {}

  /**
   * Sums the amount already taken out of the captured intent.
   *
   * BUG: this walks every refund row regardless of status, so a
   * declined ('failed') attempt — which moved zero money — still
   * subtracts from what should remain refundable.
   */
  private totalRefunded(refunds: Refund[]): number {
    return refunds.reduce((sum, r) => sum + r.amount, 0);
  }

  /**
   * Recomputes `remaining` from the refund ledger fresh on every call
   * (never from a cached running total) so that many partial refunds
   * can never cumulatively exceed the captured amount.
   */
  async assertRefundable(intentId: string, requestedAmount: number): Promise<void> {
    const intent = await this.intentRepo.findOneByOrFail({ id: intentId });

    const refunds = await this.refundRepo.find({
      where: { paymentIntentId: intentId },
    });

    const remaining = intent.amount - this.totalRefunded(refunds);

    if (requestedAmount > remaining) {
      throw new BadRequestException('Refund exceeds refundable amount');
    }
  }

  async createRefund(intentId: string, amount: number): Promise<Refund> {
    await this.assertRefundable(intentId, amount);

    const outcome: RefundStatus = await this.callGateway(intentId, amount);

    return this.refundRepo.save({
      paymentIntentId: intentId,
      amount,
      status: outcome,
    });
  }

  private async callGateway(_intentId: string, _amount: number): Promise<RefundStatus> {
    // Simulated synchronous gateway call — resolves to 'succeeded' or 'failed'.
    throw new Error('not implemented');
  }
}

/**
 * Example that reproduces the bug:
 *
 *   captured amount X = 10_000
 *   refund attempt F = 4_000, gateway declines it -> status: 'failed'
 *   customer then requests the untouched remainder = 10_000
 *
 *   totalRefunded(refunds) = 4_000 (F is summed even though it failed)
 *   remaining = 10_000 - 4_000 = 6_000
 *   requestedAmount (10_000) > remaining (6_000) -> wrongly throws 400,
 *   even though 0 of the captured amount has actually left.
 */
